	"calcurse -Q [--from <date>] [--to <date>] [--days <number>]\n"
	"calcurse -a | -d <date> | -d <number> | -n | -r[<number>] | -s[<date>] | -t[<number>]\n"
	"calcurse -h | -v | --status | -G | -P | -g | -i <file> | -x[<format>] | --daemon\n"
