static void print_usage_err(void)
{
	fputs(USAGE, stderr);
	fputs("Try `calcurse -h` for more information.\n", stderr);
}

/* ---- Option parsing ---- */

enum op_mode {
	OP_NONE = 0,
	OP_QUERY,
	OP_GREP,
	OP_PURGE,
	OP_GC,
	OP_IMPORT,
	OP_EXPORT,
	OP_STATUS,
	OP_DAEMON,
	OP_HELP,
	OP_VERSION,
};

/* Short-form query letters */
enum query_short {
	QS_NONE = 0,
	QS_A, QS_D, QS_N, QS_R, QS_S, QS_T,
};

struct cli_opts {
	enum op_mode op;
	enum query_short qs;
	char *datadir;
	char *confdir;
	char *calfile;
	char *import_file;
	char *export_fmt;
	char *d_arg;
	char *r_arg;
	char *s_arg;
	char *t_arg;
	char *from;
	char *to;
	long days;
	int have_days;
	long limit;
	int have_limit;
	char *search;
	int quiet;
	int read_only;
};

static int set_op(struct cli_opts *o, enum op_mode m)
{
	if (o->op != OP_NONE && o->op != m) {
		fprintf(stderr, "args.c: 880: invalid argument combination\n");
		return -1;
	}
	o->op = m;
	return 0;
}

/* longopt values */
enum {
	OPT_FROM = 1000,
