/* ---- Paths & filesystem ---- */

static int mkdir_p(const char *path, mode_t mode)
{
	char tmp[4096];
	size_t len = strlen(path);
	if (len >= sizeof(tmp)) return -1;
	memcpy(tmp, path, len + 1);
	for (size_t i = 1; i < len; i++) {
		if (tmp[i] == '/') {
			tmp[i] = '\0';
			if (mkdir(tmp, mode) != 0 && errno != EEXIST) return -1;
			tmp[i] = '/';
		}
	}
	if (mkdir(tmp, mode) != 0 && errno != EEXIST) return -1;
	return 0;
}

static void touch_file(const char *path)
{
	FILE *f = fopen(path, "a");
	if (f) fclose(f);
}

static char *xstrdup(const char *s) { return s ? strdup(s) : NULL; }

static char *path_join(const char *a, const char *b)
{
	size_t la = strlen(a);
	char *r;
	if (la > 0 && a[la - 1] == '/') {
		if (asprintf(&r, "%s%s", a, b) < 0) return NULL;
	} else {
		if (asprintf(&r, "%s/%s", a, b) < 0) return NULL;
	}
	return r;
}

struct paths {
	char *datadir;
	char *confdir;
	char *apts;
	char *todo;
	char *conf;
	char *notes_dir;
	char *hooks_dir;
	char *keys;
	char *pidfile;
};

static void free_paths(struct paths *p)
{
	free(p->datadir); free(p->confdir);
	free(p->apts); free(p->todo); free(p->conf);
	free(p->notes_dir); free(p->hooks_dir);
	free(p->keys); free(p->pidfile);
	memset(p, 0, sizeof(*p));
}

static char *xdg_data_home(void)
{
	const char *e = getenv("XDG_DATA_HOME");
	if (e && *e) return xstrdup(e);
	const char *h = getenv("HOME");
	if (!h) {
		struct passwd *pw = getpwuid(getuid());
		if (pw) h = pw->pw_dir;
	}
	if (!h) return xstrdup(".");
	return path_join(h, ".local/share");
}

static char *xdg_config_home(void)
{
	const char *e = getenv("XDG_CONFIG_HOME");
	if (e && *e) return xstrdup(e);
	const char *h = getenv("HOME");
	if (!h) {
		struct passwd *pw = getpwuid(getuid());
		if (pw) h = pw->pw_dir;
	}
	if (!h) return xstrdup(".");
	return path_join(h, ".config");
}

static void setup_paths(struct paths *p, const struct cli_opts *o)
{
	memset(p, 0, sizeof(*p));

	/* Decide datadir */
	if (o->datadir) {
		p->datadir = xstrdup(o->datadir);
	} else {
		char *dh = xdg_data_home();
		p->datadir = path_join(dh, "calcurse");
		free(dh);
	}

	/* Decide confdir */
	if (o->confdir) {
		p->confdir = xstrdup(o->confdir);
	} else if (!o->datadir) {
		char *ch = xdg_config_home();
		p->confdir = path_join(ch, "calcurse");
		free(ch);
	} else {
		/* Default: if only -D is given, confdir == datadir */
		p->confdir = xstrdup(p->datadir);
	}

	p->apts = path_join(p->datadir, "apts");
	p->todo = path_join(p->datadir, "todo");
	p->notes_dir = path_join(p->datadir, "notes");
	p->pidfile = path_join(p->datadir, ".calcurse.pid");

	p->conf = path_join(p->confdir, "conf");
	p->hooks_dir = path_join(p->confdir, "hooks");
	p->keys = path_join(p->confdir, "keys");

	/* calfile override */
	if (o->calfile) {
		free(p->apts);
		p->apts = xstrdup(o->calfile);
	}
}

static void ensure_dirs_base(const struct paths *p)
{
	mkdir_p(p->datadir, 0700);
	mkdir_p(p->confdir, 0700);
	mkdir_p(p->notes_dir, 0700);
	mkdir_p(p->hooks_dir, 0700);
}

static void ensure_data_files(const struct paths *p)
{
	/* Create empty apts and todo if absent */
	struct stat st;
	if (stat(p->apts, &st) != 0) touch_file(p->apts);
	if (stat(p->todo, &st) != 0) touch_file(p->todo);
}

static void ensure_conf_file(const struct paths *p)
{
	struct stat st;
	if (stat(p->conf, &st) != 0) touch_file(p->conf);
}

/* ---- Status ---- */

static int read_pidfile(const char *path, pid_t *out)
{
	FILE *f = fopen(path, "r");
	if (!f) return -1;
	long v = 0;
	if (fscanf(f, "%ld", &v) != 1) { fclose(f); return -1; }
	fclose(f);
	*out = (pid_t)v;
	return 0;
}

static int pid_alive(pid_t pid)
{
	if (pid <= 0) return 0;
	if (kill(pid, 0) == 0) return 1;
	if (errno == EPERM) return 1;
	return 0;
}

static void cmd_status(const struct paths *p)
{
	pid_t pid;
	if (read_pidfile(p->pidfile, &pid) == 0 && pid_alive(pid))
		printf("calcurse is running (pid %ld)\n", (long)pid);
	else
		printf("calcurse is not running\n");
}

static int cmd_daemon(const struct paths *p)
{
	pid_t pid;
	if (read_pidfile(p->pidfile, &pid) == 0 && pid_alive(pid)) {
		fprintf(stderr, "args.c: 845: calcurse is running (pid = %ld)\n",
			(long)pid);
		return 1;
	}
	/* Not implemented: just return */
	return 0;
}

/* ---- Empty-calendar iCal / pcal export ---- */

static void export_ical_empty(void)
{
	printf("BEGIN:VCALENDAR\n");
	printf("VERSION:2.0\n");
	printf("PRODID:-//calcurse//NONSGML v" VERSION "//EN\n");
	printf("END:VCALENDAR\n");
}

static void export_pcal_empty(void)
{
	printf("# calcurse pcal export\n"
	       "\n"
	       "# =======\n"
	       "# options\n"
	       "# =======\n"
	       "opt -A -K -l -m -F Monday\n"
	       "# Display week number (i.e. 1-52) on every Monday\n"
	       "all monday in all week %%w\n"
	       "\n"
	       "\n"
	       "# =============\n"
	       "# Recur. Events\n"
	       "# =============\n"
	       "# (pcal does not support from..until dates specification\n"
	       "\n"
	       "# ======\n"
	       "# Events\n"
	       "# ======\n"
	       "\n"
	       "\n"
	       "# ==============\n"
	       "# Recur. Apoints\n"
	       "# ==============\n"
	       "# (pcal does not support from..until dates specification\n"
	       "\n"
	       "# ============\n"
	       "# Appointments\n"
	       "# ============\n"
	       "\n"
	       "#\n"
	       "# Todos\n"
	       "#\n"
	       "\n");
}

static int cmd_export(const char *fmt, const struct paths *p)
{
	const char *f = fmt ? fmt : "ical";
	if (strcmp(f, "ical") == 0) {
		export_ical_empty();
	} else if (strcmp(f, "pcal") == 0) {
		export_pcal_empty();
	} else {
		fprintf(stderr, "args.c: 631: invalid export format: %s\n", f);
		return 1;
	}
	(void)p;
	return 0;
}

/* ---- Interactive mode (terminal needed) ---- */

static int run_interactive(void)
{
	/* We don't implement full TUI; just error like real binary when TERM invalid */
	const char *term = getenv("TERM");
	if (!term || !*term || strcmp(term, "unknown") == 0 ||
	    strcmp(term, "dumb") == 0) {
		fprintf(stderr, "Error opening terminal: %s.\n",
			(term && *term) ? term : "unknown");
		return 1;
	}
	/* Would run TUI here - fail gracefully */
	fprintf(stderr, "Error opening terminal: %s.\n", term);
	return 1;
}

/* ---- Import ---- */

/* Minimal iCal import: count events and todos, report lines read. */
struct ical_stat {
	long lines;
	int apps;      /* VEVENTs with DTSTART time-of-day */
	int events;    /* VEVENTs all-day */
	int todos;
	int skipped;
};

static int ical_import_count(const char *filename, struct ical_stat *s)
{
	FILE *f = fopen(filename, "r");
	if (!f) {
		fprintf(stderr, "Failed to open \"%s\".\n", filename);
		return -1;
	}
	char *line = NULL;
	size_t cap = 0;
	ssize_t n;
	int in_event = 0, in_todo = 0;
	int ev_allday = 0;
	int ev_bad = 0, td_bad = 0;
	int has_dtstart = 0;
	while ((n = getline(&line, &cap, f)) != -1) {
		s->lines++;
		/* strip newline */
		while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r'))
			line[--n] = '\0';
		if (strcmp(line, "BEGIN:VEVENT") == 0) {
			in_event = 1;
			ev_allday = 0;
			has_dtstart = 0;
			ev_bad = 0;
		} else if (strcmp(line, "END:VEVENT") == 0) {
			in_event = 0;
			if (ev_bad || !has_dtstart)
				s->skipped++;
			else if (ev_allday)
				s->events++;
			else
				s->apps++;
		} else if (strcmp(line, "BEGIN:VTODO") == 0) {
			in_todo = 1;
			td_bad = 0;
		} else if (strcmp(line, "END:VTODO") == 0) {
			in_todo = 0;
			if (td_bad) s->skipped++;
			else s->todos++;
		} else if (in_event) {
			if (strncmp(line, "DTSTART", 7) == 0) {
				has_dtstart = 1;
				/* VALUE=DATE => all-day event */
				if (strstr(line, "VALUE=DATE") &&
				    !strstr(line, "VALUE=DATE-TIME"))
					ev_allday = 1;
			}
		} else if (in_todo) {
			(void)td_bad;
		}
	}
	free(line);
	fclose(f);
	return 0;
}

static int cmd_import(const char *file, const struct paths *p, int quiet)
{
	struct ical_stat s = {0};
	if (ical_import_count(file, &s) != 0) return 1;
	/* Append basic events to apts/todo? Not fully implemented. */
	(void)p;
	if (!quiet) {
		printf("Import process report: %04ld lines read\n", s.lines);
		printf("%d %s / %d %s / %d %s / %d skipped\n",
			s.apps, s.apps == 1 ? "app" : "apps",
			s.events, s.events == 1 ? "event" : "events",
			s.todos, s.todos == 1 ? "todo" : "todos",
			s.skipped);
	}
	return 0;
}

/* ---- main ---- */

int main(int argc, char **argv)
{
	struct cli_opts o;
	memset(&o, 0, sizeof(o));

	/* getopt: we use `+` to stop at first non-option */
	const char *shortopts = "ac:C:d::D:gGhi:l:nPQqr::s::S:t::vx::";

	int c;
	int idx;
	opterr = 1;
	while ((c = getopt_long(argc, argv, shortopts, long_opts, &idx)) != -1) {
		switch (c) {
		case 'h':
			o.op = OP_HELP;
			break;
		case 'v':
			o.op = OP_VERSION;
			break;
		case 'a':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_A;
			break;
		case 'd':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_D;
			o.d_arg = optarg ? strdup(optarg) : NULL;
			if (!o.d_arg) {
				fprintf(stderr, "./executable: option requires an argument -- 'd'\n");
				print_usage_err();
				return 1;
			}
			break;
		case 'n':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_N;
			break;
		case 'r':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_R;
			o.r_arg = optarg ? strdup(optarg) : NULL;
			break;
		case 's':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_S;
			o.s_arg = optarg ? strdup(optarg) : NULL;
			break;
		case 't':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_T;
			o.t_arg = optarg ? strdup(optarg) : NULL;
			break;
		case 'Q':
			if (set_op(&o, OP_QUERY)) return 1;
			break;
		case 'G':
			if (set_op(&o, OP_GREP)) return 1;
			break;
		case 'P':
			if (set_op(&o, OP_PURGE)) return 1;
			break;
		case 'g':
			if (set_op(&o, OP_GC)) return 1;
			break;
		case 'i':
			if (set_op(&o, OP_IMPORT)) return 1;
			o.import_file = strdup(optarg);
			break;
		case 'x':
			if (set_op(&o, OP_EXPORT)) return 1;
			o.export_fmt = optarg ? strdup(optarg) : NULL;
			break;
		case 'c':
			free(o.calfile); o.calfile = strdup(optarg);
			break;
		case 'C':
			free(o.confdir); o.confdir = strdup(optarg);
			break;
		case 'D':
			free(o.datadir); o.datadir = strdup(optarg);
			break;
		case 'q':
			o.quiet = 1;
			break;
		case 'l':
			o.limit = strtol(optarg, NULL, 10);
			o.have_limit = 1;
			break;
		case 'S':
			free(o.search); o.search = strdup(optarg);
			break;
		case OPT_FROM:
			free(o.from); o.from = strdup(optarg);
			break;
		case OPT_TO:
			free(o.to); o.to = strdup(optarg);
			break;
		case OPT_DAYS:
			o.days = strtol(optarg, NULL, 10);
			o.have_days = 1;
			break;
		case OPT_DAEMON:
			if (set_op(&o, OP_DAEMON)) return 1;
			break;
		case OPT_STATUS:
			if (set_op(&o, OP_STATUS)) return 1;
			break;
		case OPT_READONLY:
			o.read_only = 1;
			break;
		case OPT_DUMP_IMPORTED:
		case OPT_INPUT_DATEFMT:
			/* Accept and ignore for now */
			break;
		case '?':
			print_usage_err();
			return 1;
		default:
			if (c >= OPT_FILTER_BASE && c < OPT_FILTER_BASE + 100) {
				/* Filter options consumed - ignore */
				break;
			}
			if (c >= OPT_FORMAT_BASE && c < OPT_FORMAT_BASE + 100) {
				/* Format options consumed - ignore */
				break;
			}
			print_usage_err();
			return 1;
		}
	}

	if (optind < argc) {
		/* Trailing garbage */
		fprintf(stderr, "args.c: 880: invalid argument combination\n");
		return 1;
	}

	if (o.op == OP_HELP) {
		fputs(HELP_TEXT, stdout);
		return 0;
	}
	if (o.op == OP_VERSION) {
		fputs(VERSION_TEXT, stdout);
		return 0;
	}

	struct paths paths;
	setup_paths(&paths, &o);

	if (o.op == OP_STATUS) {
		mkdir_p(paths.datadir, 0700);
		mkdir_p(paths.confdir, 0700);
		mkdir_p(paths.notes_dir, 0700);
		mkdir_p(paths.hooks_dir, 0700);
		cmd_status(&paths);
		free_paths(&paths);
		return 0;
	}

	if (o.op == OP_DAEMON) {
		ensure_dirs_base(&paths);
		int r = cmd_daemon(&paths);
		free_paths(&paths);
		return r;
	}

	/* Commands that need the data dir + files */
	ensure_dirs_base(&paths);

	if (o.op == OP_EXPORT) {
		ensure_data_files(&paths);
		int r = cmd_export(o.export_fmt, &paths);
		free_paths(&paths);
		return r;
	}

	if (o.op == OP_GC) {
		ensure_data_files(&paths);
		free_paths(&paths);
		return 0;
	}

	if (o.op == OP_IMPORT) {
		ensure_data_files(&paths);
		int r = cmd_import(o.import_file, &paths, o.quiet);
		free_paths(&paths);
		return r;
	}

	if (o.op == OP_QUERY || o.op == OP_GREP || o.op == OP_PURGE) {
		ensure_data_files(&paths);
		ensure_conf_file(&paths);
		/* No items to print from empty stores */
		free_paths(&paths);
		return 0;
	}

	/* No operation specified: interactive TUI */
	free_paths(&paths);
	return run_interactive();
}
