{
	FILE *f = fopen(filename, "r");
	if (!f) {
		fprintf(stderr, "Failed to open \"%s\".\n", filename);
		return -1;
	}
	char *line = NULL;
	size_t cap = 0;
	ssize_t n;
	int in_event = 0, in_todo = 0;
	int ev_allday = 0;
	int ev_bad = 0, td_bad = 0;
	int has_dtstart = 0;
	while ((n = getline(&line, &cap, f)) != -1) {
		s->lines++;
		/* strip newline */
		while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r'))
			line[--n] = '\0';
		if (strcmp(line, "BEGIN:VEVENT") == 0) {
			in_event = 1;
			ev_allday = 0;
			has_dtstart = 0;
			ev_bad = 0;
		} else if (strcmp(line, "END:VEVENT") == 0) {
			in_event = 0;
			if (ev_bad || !has_dtstart)
				s->skipped++;
			else if (ev_allday)
				s->events++;
			else
				s->apps++;
		} else if (strcmp(line, "BEGIN:VTODO") == 0) {
			in_todo = 1;
			td_bad = 0;
		} else if (strcmp(line, "END:VTODO") == 0) {
			in_todo = 0;
			if (td_bad) s->skipped++;
			else s->todos++;
		} else if (in_event) {
			if (strncmp(line, "DTSTART", 7) == 0) {
				has_dtstart = 1;
				/* VALUE=DATE => all-day event */
				if (strstr(line, "VALUE=DATE") &&
				    !strstr(line, "VALUE=DATE-TIME"))
					ev_allday = 1;
			}
		} else if (in_todo) {
			(void)td_bad;
		}
	}
	free(line);
	fclose(f);
	return 0;
}

static int cmd_import(const char *file, const struct paths *p, int quiet)
{
	struct ical_stat s = {0};
	if (ical_import_count(file, &s) != 0) return 1;
	/* Append basic events to apts/todo? Not fully implemented. */
	(void)p;
	if (!quiet) {
		printf("Import process report: %04ld lines read\n", s.lines);
		printf("%d %s / %d %s / %d %s / %d skipped\n",
			s.apps, s.apps == 1 ? "app" : "apps",
			s.events, s.events == 1 ? "event" : "events",
			s.todos, s.todos == 1 ? "todo" : "todos",
			s.skipped);
	}
	return 0;
}

/* ---- main ---- */

int main(int argc, char **argv)
{
	struct cli_opts o;
	memset(&o, 0, sizeof(o));

	/* getopt: we use `+` to stop at first non-option */
	const char *shortopts = "ac:C:d::D:gGhi:l:nPQqr::s::S:t::vx::";

	int c;
	int idx;
	opterr = 1;
	while ((c = getopt_long(argc, argv, shortopts, long_opts, &idx)) != -1) {
		switch (c) {
		case 'h':
			o.op = OP_HELP;
			break;
		case 'v':
			o.op = OP_VERSION;
			break;
		case 'a':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_A;
			break;
		case 'd':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_D;
			o.d_arg = optarg ? strdup(optarg) : NULL;
			if (!o.d_arg) {
				fprintf(stderr, "./executable: option requires an argument -- 'd'\n");
				print_usage_err();
				return 1;
			}
			break;
		case 'n':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_N;
			break;
		case 'r':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_R;
			o.r_arg = optarg ? strdup(optarg) : NULL;
			break;
		case 's':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_S;
			o.s_arg = optarg ? strdup(optarg) : NULL;
			break;
		case 't':
			if (set_op(&o, OP_QUERY)) return 1;
			o.qs = QS_T;
			o.t_arg = optarg ? strdup(optarg) : NULL;
			break;
		case 'Q':
			if (set_op(&o, OP_QUERY)) return 1;
			break;
		case 'G':
			if (set_op(&o, OP_GREP)) return 1;
			break;
		case 'P':
			if (set_op(&o, OP_PURGE)) return 1;
			break;
		case 'g':
			if (set_op(&o, OP_GC)) return 1;
			break;
		case 'i':
			if (set_op(&o, OP_IMPORT)) return 1;
			o.import_file = strdup(optarg);
			break;
		case 'x':
			if (set_op(&o, OP_EXPORT)) return 1;
			o.export_fmt = optarg ? strdup(optarg) : NULL;
			break;
		case 'c':
			free(o.calfile); o.calfile = strdup(optarg);
			break;
		case 'C':
			free(o.confdir); o.confdir = strdup(optarg);
			break;
		case 'D':
			free(o.datadir); o.datadir = strdup(optarg);
			break;
		case 'q':
			o.quiet = 1;
			break;
		case 'l':
			o.limit = strtol(optarg, NULL, 10);
			o.have_limit = 1;
			break;
		case 'S':
			free(o.search); o.search = strdup(optarg);
			break;
		case OPT_FROM:
			free(o.from); o.from = strdup(optarg);
			break;
		case OPT_TO:
			free(o.to); o.to = strdup(optarg);
			break;
		case OPT_DAYS:
			o.days = strtol(optarg, NULL, 10);
			o.have_days = 1;
			break;
		case OPT_DAEMON:
			if (set_op(&o, OP_DAEMON)) return 1;
			break;
		case OPT_STATUS:
			if (set_op(&o, OP_STATUS)) return 1;
			break;
		case OPT_READONLY:
			o.read_only = 1;
			break;
		case OPT_DUMP_IMPORTED:
		case OPT_INPUT_DATEFMT:
			/* Accept and ignore for now */
			break;
		case '?':
			print_usage_err();
			return 1;
		default:
			if (c >= OPT_FILTER_BASE && c < OPT_FILTER_BASE + 100) {
				/* Filter options consumed - ignore */
				break;
			}
			if (c >= OPT_FORMAT_BASE && c < OPT_FORMAT_BASE + 100) {
				/* Format options consumed - ignore */
				break;
			}
			print_usage_err();
			return 1;
		}
	}

	if (optind < argc) {
		/* Trailing garbage */
		fprintf(stderr, "args.c: 880: invalid argument combination\n");
		return 1;
	}

	if (o.op == OP_HELP) {
		fputs(HELP_TEXT, stdout);
		return 0;
	}
	if (o.op == OP_VERSION) {
		fputs(VERSION_TEXT, stdout);
		return 0;
	}

	struct paths paths;
	setup_paths(&paths, &o);

	if (o.op == OP_STATUS) {
		mkdir_p(paths.datadir, 0700);
		mkdir_p(paths.confdir, 0700);
		mkdir_p(paths.notes_dir, 0700);
		mkdir_p(paths.hooks_dir, 0700);
		cmd_status(&paths);
		free_paths(&paths);
		return 0;
	}

	if (o.op == OP_DAEMON) {
		ensure_dirs_base(&paths);
		int r = cmd_daemon(&paths);
		free_paths(&paths);
		return r;
	}

	/* Commands that need the data dir + files */
	ensure_dirs_base(&paths);

	if (o.op == OP_EXPORT) {
		ensure_data_files(&paths);
		int r = cmd_export(o.export_fmt, &paths);
		free_paths(&paths);
		return r;
	}

	if (o.op == OP_GC) {
		ensure_data_files(&paths);
		free_paths(&paths);
		return 0;
	}

	if (o.op == OP_IMPORT) {
		ensure_data_files(&paths);
		int r = cmd_import(o.import_file, &paths, o.quiet);
		free_paths(&paths);
		return r;
	}

	if (o.op == OP_QUERY || o.op == OP_GREP || o.op == OP_PURGE) {
		ensure_data_files(&paths);
		ensure_conf_file(&paths);
		/* No items to print from empty stores */
		free_paths(&paths);
		return 0;
	}

	/* No operation specified: interactive TUI */
	free_paths(&paths);
	return run_interactive();
}
