/* ---- Paths & filesystem ---- */

static int mkdir_p(const char *path, mode_t mode)
{
	char tmp[4096];
	size_t len = strlen(path);
	if (len >= sizeof(tmp)) return -1;
	memcpy(tmp, path, len + 1);
	for (size_t i = 1; i < len; i++) {
		if (tmp[i] == '/') {
			tmp[i] = '\0';
			if (mkdir(tmp, mode) != 0 && errno != EEXIST) return -1;
			tmp[i] = '/';
		}
	}
	if (mkdir(tmp, mode) != 0 && errno != EEXIST) return -1;
	return 0;
}

static void touch_file(const char *path)
{
	FILE *f = fopen(path, "a");
	if (f) fclose(f);
}

static char *xstrdup(const char *s) { return s ? strdup(s) : NULL; }

static char *path_join(const char *a, const char *b)
{
	size_t la = strlen(a);
	char *r;
	if (la > 0 && a[la - 1] == '/') {
		if (asprintf(&r, "%s%s", a, b) < 0) return NULL;
	} else {
		if (asprintf(&r, "%s/%s", a, b) < 0) return NULL;
	}
	return r;
}

struct paths {
	char *datadir;
	char *confdir;
	char *apts;
	char *todo;
	char *conf;
	char *notes_dir;
	char *hooks_dir;
	char *keys;
	char *pidfile;
};

static void free_paths(struct paths *p)
{
	free(p->datadir); free(p->confdir);
	free(p->apts); free(p->todo); free(p->conf);
	free(p->notes_dir); free(p->hooks_dir);
	free(p->keys); free(p->pidfile);
	memset(p, 0, sizeof(*p));
}

static char *xdg_data_home(void)
{
	const char *e = getenv("XDG_DATA_HOME");
	if (e && *e) return xstrdup(e);
	const char *h = getenv("HOME");
	if (!h) {
		struct passwd *pw = getpwuid(getuid());
		if (pw) h = pw->pw_dir;
	}
	if (!h) return xstrdup(".");
	return path_join(h, ".local/share");
}

static char *xdg_config_home(void)
{
	const char *e = getenv("XDG_CONFIG_HOME");
	if (e && *e) return xstrdup(e);
	const char *h = getenv("HOME");
	if (!h) {
		struct passwd *pw = getpwuid(getuid());
		if (pw) h = pw->pw_dir;
	}
	if (!h) return xstrdup(".");
	return path_join(h, ".config");
}

static void setup_paths(struct paths *p, const struct cli_opts *o)
{
	memset(p, 0, sizeof(*p));

	/* Decide datadir */
	if (o->datadir) {
		p->datadir = xstrdup(o->datadir);
	} else {
		char *dh = xdg_data_home();
		p->datadir = path_join(dh, "calcurse");
		free(dh);
	}

	/* Decide confdir */
	if (o->confdir) {
		p->confdir = xstrdup(o->confdir);
	} else if (!o->datadir) {
		char *ch = xdg_config_home();
		p->confdir = path_join(ch, "calcurse");
		free(ch);
	} else {
		/* Default: if only -D is given, confdir == datadir */
		p->confdir = xstrdup(p->datadir);
	}

	p->apts = path_join(p->datadir, "apts");
	p->todo = path_join(p->datadir, "todo");
	p->notes_dir = path_join(p->datadir, "notes");
	p->pidfile = path_join(p->datadir, ".calcurse.pid");

	p->conf = path_join(p->confdir, "conf");
	p->hooks_dir = path_join(p->confdir, "hooks");
	p->keys = path_join(p->confdir, "keys");

	/* calfile override */
	if (o->calfile) {
		free(p->apts);
		p->apts = xstrdup(o->calfile);
	}
