	struct stat st;
	if (stat(p->apts, &st) != 0) touch_file(p->apts);
	if (stat(p->todo, &st) != 0) touch_file(p->todo);
}

static void ensure_conf_file(const struct paths *p)
{
	struct stat st;
	if (stat(p->conf, &st) != 0) touch_file(p->conf);
}

/* ---- Status ---- */

static int read_pidfile(const char *path, pid_t *out)
{
	FILE *f = fopen(path, "r");
	if (!f) return -1;
	long v = 0;
	if (fscanf(f, "%ld", &v) != 1) { fclose(f); return -1; }
	fclose(f);
	*out = (pid_t)v;
	return 0;
}

static int pid_alive(pid_t pid)
{
	if (pid <= 0) return 0;
	if (kill(pid, 0) == 0) return 1;
	if (errno == EPERM) return 1;
	return 0;
}

static void cmd_status(const struct paths *p)
{
	pid_t pid;
	if (read_pidfile(p->pidfile, &pid) == 0 && pid_alive(pid))
		printf("calcurse is running (pid %ld)\n", (long)pid);
	else
		printf("calcurse is not running\n");
}

static int cmd_daemon(const struct paths *p)
{
	pid_t pid;
	if (read_pidfile(p->pidfile, &pid) == 0 && pid_alive(pid)) {
		fprintf(stderr, "args.c: 845: calcurse is running (pid = %ld)\n",
			(long)pid);
		return 1;
	}
	/* Not implemented: just return */
	return 0;
}

/* ---- Empty-calendar iCal / pcal export ---- */

static void export_ical_empty(void)
{
